namespace ghidra.features.bsim.gui.filters;









using docking.widgets.textfield;
using ghidra.util;
using utility.function;

/**
 * A BSimValueEditor for filters with arbitrary string values. Supports comma separated values.
 */
public class StringBSimValueEditor : BSimValueEditor {

	private BSimFilterType filterType;
	private Callback listener;
	private HintTextField textField;
	private bool isValid;

	public StringBSimValueEditor(BSimFilterType filterType, List<string> initialValues,
		Callback listener) {
		this.filterType = filterType;
		this.listener = Callback.dummyIfNull(listener);
		textField = new HintTextField(filterType.getHint());
		textField.setColumns(20);
		setValues(initialValues);
		textField.getDocument().addDocumentListener(new _Anon_DocumentListener_1());
		checkValid();
	}

	protected void documentChanged() {
		Swing.runLater(() => {
			checkValid();
			listener.call();
		});
	}

	/* @Override */
	public void setValues(List<string> values) {
		if (values == null) {
			textField.setText("");
		}
		else {
			string value = values.stream().collect(Collectors.joining(", "));
			textField.setText(value);
		}

	}

	/* @Override */
	public List<string> getValues() {
		string text = textField.getText().trim();
		if (text.contains(",")) {
			List<string> values = new();
			string[] vals = text.split(FILTER_DELIMETER);
			foreach (string val in vals) {
				if (val == null || val.isBlank()) {
					continue;
				}
				values.add(val.trim());
			}
			return values;
		}
		return List.of(text);
	}

	/* @Override */
	public JComponent getComponent() {
		return textField;
	}

	/* @Override */
	public bool hasValidValues() {
		return isValid;
	}

	private void checkValid() {
		isValid = checkForValidValues();
		textField.setBackground(isValid ? VALID_COLOR : INVALID_COLOR);
	}

	private bool checkForValidValues() {
		List<string> values = getValues();
		if (values == null || values.size() == 0) {
			return filterType.isValidValue("");
		}
		foreach (string string in values) {
			if (!filterType.isValidValue(string)) {
				return false;
			}
		}
		return true;
	}


	internal class _Anon_DocumentListener_1 : DocumentListener
	{


			/* @Override */
			public void removeUpdate(DocumentEvent e) {
				documentChanged();
			}

			/* @Override */
			public void insertUpdate(DocumentEvent e) {
				documentChanged();
			}

			/* @Override */
			public void changedUpdate(DocumentEvent e) {
				documentChanged();
			}
		
	}

}
